package io.morin.archicode.viewpoint.kernel;

import com.dylibso.chicory.runtime.Instance;
import java.nio.charset.StandardCharsets;
import lombok.val;

/**
 * The viewpoint kernel: the algorithms of the overview, detailed and deep viewpoints, written in Rust (see
 * {@code src/main/rust/viewpoint-kernel}) and compiled to WebAssembly. The standalone editor runs the very same
 * module, so a diagram drawn in a browser and a view generated by the CLI cannot differ.
 * <p>
 * The module is translated to JVM bytecode when the project is built (Chicory's compiler plugin, see the pom), so
 * there is neither an interpreter nor any code generation at run time, and it works in a native image.
 * <p>
 * It is a pure function: JSON in, JSON out. See {@link KernelViewpointFactory} for what goes in and what comes out.
 */
public final class ViewpointKernel {

    /** The version of the input/output contract this class and {@link KernelViewpointFactory} were written for. */
    public static final int CONTRACT_VERSION = 5;

    private static final class Holder {

        static final ViewpointKernel INSTANCE = new ViewpointKernel();
    }

    private final Instance instance;

    private ViewpointKernel() {
        this.instance = Instance.builder(ViewpointKernelModule.load())
            .withMachineFactory(ViewpointKernelModule::create)
            .build();
    }

    public static ViewpointKernel getInstance() {
        return Holder.INSTANCE;
    }

    /**
     * Run the kernel.
     *
     * @param json the input, as JSON
     * @return the output, as JSON: the view, or {@code {"error": "..."}}
     */
    public synchronized String compute(String json) {
        return call("compute", json);
    }

    /**
     * Apply the actions of a facet to the JSON of a workspace.
     *
     * @param json {@code {"workspace": {...}, "actions": [{"operator": "REMOVE", "json_path": "..."}]}}
     * @return {@code {"version", "workspace", "warnings"}}, or {@code {"error": "..."}}
     */
    public synchronized String applyFacet(String json) {
        return call("apply_facet", json);
    }

    /**
     * Apply the ordered patches of a plateau ({@code REMOVE}, {@code SET}, {@code ADD}, {@code MERGE}) to the JSON of a
     * workspace. A patch that selects nothing is an error that names the plateau, the rank of the patch and its selector.
     *
     * @param json {@code {"workspace": {...}, "plateau": "id", "patches": [{"operator": "REMOVE", "target": "shop.web"}]}}
     * @return {@code {"version", "workspace", "patches": [{"rank", "operator", "selector", "matched", "touched", ...}]}},
     *         or {@code {"error": "...", "patch": {"plateau", "rank", "operator", "selector"}}}
     */
    public synchronized String applyPatches(String json) {
        return call("apply_patches", json);
    }

    /**
     * The seven words of the states of a comparison, said once by the kernel (contract 5): see {@link KernelStates}, which reads them.
     *
     * @return {@code {"version", "relationship", "identity", "container", "states"}}
     */
    public synchronized String states() {
        return call("states", "{}");
    }

    /**
     * Compare two plateaus of an architecture: what is new, changed and removed from one to the other.
     *
     * @param json {@code {"base": {"application": [element], "technology": [element]}, "target": {...}, "on_one_chain": bool}}, the elements
     *             being the ones {@link #compute} takes, with {@code kind}, {@code name}, {@code description},
     *             {@code qualifiers} and {@code tags}, and for an element of the target that says what it
     *             replaces, {@code replaces}; {@code on_one_chain} says whether one of the two plateaus is the past of the
     *             other (an ancestor in the tree of plateaus): it is required, the kernel refuses an input without it
     *             (contract 5, issue #70)
     * @return {@code {"version", "elements", "relationships", "changes", "counts", "candidates", "warnings"?}}, or
     *         {@code {"error": "..."}}
     */
    public synchronized String compare(String json) {
        return call("compare", json);
    }

    private String call(String function, String json) {
        val bytes = json.getBytes(StandardCharsets.UTF_8);
        val pointer = (int) instance.export("alloc").apply(bytes.length)[0];
        try {
            instance.memory().write(pointer, bytes);
            val length = (int) instance.export(function).apply(pointer, bytes.length)[0];
            val resultPointer = (int) instance.export("result_ptr").apply()[0];
            return instance.memory().readString(resultPointer, length);
        } finally {
            instance.export("dealloc").apply(pointer, bytes.length);
        }
    }
}
